pieces = {
'3a':(3,[(1,2),(1,3)]), '3b':(3,[(5,4),(5,5)]), '3c':(3,[(8,0),(9,0)]),
'6a':(6,[(1,7),(2,7)]), '6b':(6,[(4,8),(4,9)]),
'7':(7,[(2,5),(3,5)]), '8':(8,[(3,1),(3,2)]), '9':(9,[(6,2),(7,2)]),
'4':(4,[(6,8),(7,8)]), '1':(1,[(8,5),(8,6)]), '5':(5,[(9,7),(9,8)]) }
# move in order of min row, and calculate max shift until row >= 1 and doesn't overlap settled shapes
settled={}; positions={}
for name,(color,cells) in sorted(pieces.items(), key=lambda kv:min(r for r,c in kv[1][1])):
    shift=0
    while True:
        candidate=[(r-shift-1,c) for r,c in cells]
        occupied={p for cc,ps in settled.values() for p in ps}
        if any(r < 1 or (r,c) in occupied for r,c in candidate): break
        shift += 1
    moved=[(r-shift,c) for r,c in cells]
    settled[name]=(color,moved)
    positions[name]=moved
positions
